(window.CsqPacks = window.CsqPacks || {})["robo-route"] = Object.assign(window.CsqPacks["robo-route"] || {}, { "ru": {"strings":{"1":"1","2":"2","4":"4","5":"5","6":"6","8":"8","9":"9","10":"10","Two on one device":"Вдвоём на одном устройстве","Pair mode on: take turns driving.":"Режим пары включён: ведите по очереди.","Pair mode off":"Режим пары выключен","Snap blocks together and drive Bolt the robot to the goal!":"Соединяй блоки и веди робота Болта к цели!","Pick a chapter":"Выбери главу","Grade band":"Группа классов","{band} band":"Группа {band}","Quest Card":"Карточка задания","Daily Crew Challenge":"Ежедневное задание команды","{n} stars":{"one":"{n} звезда","few":"{n} звезды","many":"{n} звёзд","other":"{n} звезды"},"One new board today":"Сегодня одно новое поле","{n} Explorer stars":{"one":"{n} звезда Исследователя","few":"{n} звезды Исследователя","many":"{n} звёзд Исследователя","other":"{n} звезды Исследователя"},"{done}/{total} tasks":"Задачи: {done}/{total}","{done}/{total} levels":"Уровни: {done}/{total}","Crown":"Корона","Quest code":"Код задания","Type the four digits from your teacher":"Введи четыре цифры, которые дал учитель","A friend tests your level":"Друг проверяет твой уровень","{chapter} · Level {n}":"{chapter} · Уровень {n}","Class quest: {chapter} · {band}":"Задание класса: {chapter} · {band}","Swap! The navigator drives now.":"Смена! Теперь ведёт штурман.","Driver":"Водитель","Navigator":"Штурман","Pair mode: player {n} drives":"Режим пары: ведёт игрок {n}","Test {n}":"Тест {n}","passed":"пройден","failed":"не пройден","Blocks: {n} · goal {max} or fewer":"Блоки: {n} · цель {max} или меньше","Edits: {n}":"Правок: {n}","{n} edits from the starter program":{"one":"{n} правка от начальной программы","few":"{n} правки от начальной программы","many":"{n} правок от начальной программы","other":"{n} правки от начальной программы"},"The board: {w} by {h} squares":"Поле: {w} на {h} клеток","Door: {rule}":"Дверь: {rule}","{name} is {value}":"{name} равно {value}","Blocks":"Блоки","Put the plan lines in order first.":"Сначала расставь строки плана по порядку.","Pick a route first: run both and choose one.":"Сначала выбери маршрут: запусти оба и выбери один.","A when block goes at the top of the program.":"Блок когда ставится в самый верх программы.","A My Block goes at the top of the program.":"Мой блок ставится в самый верх программы.","Added {block}":"Добавлен блок: {block}","{a} {op} {b}":"{a} {op} {b}","not {x}":"не {x}","repeat until {x}":"повторять до {x}","repeat {n} times":{"one":"повторить {n} раз","few":"повторить {n} раза","many":"повторить {n} раз","other":"повторить {n} раза"},"if {c}":"если {c}","when {e}":"когда {e}","set {v} to {x}":"задать {v} = {x}","change {v} by {n}":"изменить {v} на {n}","My Block {name}":"Мой блок {name}","call {name}":"вызвать {name}","Tap a block on the shelf to start your program.":"Нажми на блок на полке, чтобы начать программу.","start here":"начни здесь","Undo":"Отменить","Start over":"Начать заново","Clear program":"Очистить программу","Put the next block here":"Поставь следующий блок сюда","inside":"внутри","else":"иначе","end":"конец","Route {x}":"Маршрут {x}","{n} blocks":{"one":"{n} блок","few":"{n} блока","many":"{n} блоков","other":"{n} блока"},"Run {x}":"Запустить {x}","Use {x}":"Взять {x}","Route {x} is in the program. Make it better, then run it.":"Маршрут {x} в программе. Улучши его, потом запусти.","Move up":"Вверх","Move down":"Вниз","Delete block":"Удалить блок","Change":"Изменить","Note chip":"Заметка","Credit line":"Строка автора","Move into the block above":"В блок выше","Move into the else part":"В часть иначе","Wrap the blocks below":"Охватить блоки ниже","Move out of its block":"Вынуть из блока","Add else":"Добавить иначе","Add after this block":"Добавить после этого блока","Done":"Готово","Less":"Меньше","More":"Больше","How many times?":"Сколько раз?","Use {p}":"Использовать {p}","a box":"коробка","Takes a number: {p}":"Принимает число: {p}","First question":"Первый вопрос","Second question":"Второй вопрос","on":"вкл","off":"выкл","not":"не","What does {name} do?":"Что делает {name}?","Stop":"Стоп","Run":"Пуск","Make a block, then call it. Run wakes up when the program calls a block.":"Создай блок, потом вызови его. Пуск оживёт, когда программа вызовет блок.","Routes":"Маршруты","Step":"Шаг","Reset":"Сначала","Hint":"Подсказка","Learn":"Узнать","Back to the maker":"Назад в конструктор","Skip level":"Пропустить уровень","Chapter map":"Карта глав","Hints open after two tries at Pro: one more run.":"На уровне Профи подсказки открываются после двух попыток: ещё один запуск.","Run your program first. Hints open after two tries at Pro.":"Сначала запусти программу. На уровне Профи подсказки открываются после двух попыток.","Run your program first. Hints open after a try.":"Сначала запусти программу. Подсказки откроются после попытки.","Not yet.":"Пока нет.","The program is empty. Tap a block on the shelf.":"Программа пуста. Нажми на блок на полке.","Board {n} of {total}":"Поле {n} из {total}","Route {x} works: {n} blocks.":{"one":"Маршрут {x} работает: {n} блок.","few":"Маршрут {x} работает: {n} блока.","many":"Маршрут {x} работает: {n} блоков.","other":"Маршрут {x} работает: {n} блока."},"Route {x} fails. {why}":"Маршрут {x} не работает. {why}","Bump! A wall after step {n}.":"Бум! Стена после шага {n}.","Splash!":"Плюх!","Nothing to pick up here.":"Здесь нечего поднять.","Hints are open now.":"Подсказки открыты.","Tested! Your friend solved it.":"Проверено! Твой друг прошёл уровень.","Bolt made it!":"Болт справился!","Level tested!":"Уровень проверен!","Daily Crew Challenge done!":"Ежедневное задание команды выполнено!","Fix it in {n} edits or fewer for the next star.":"Исправь не больше чем за {n} правки, чтобы получить следующую звезду.","Use {n} blocks or fewer for the next star.":"Используй не больше {n} блоков, чтобы получить следующую звезду.","Solve it without the third hint for the next star.":"Реши без третьей подсказки, чтобы получить следующую звезду.","Chapter: {n} stars":"Звёзды за главу: {n}","Level {n} done!":"Уровень {n} пройден!","Level skipped":"Уровень пропущен","Quest complete!":"Задание выполнено!","{chapter} complete!":"Глава «{chapter}» пройдена!","Great work. Tell your teacher you finished, or play the chapter again for more stars.":"Отличная работа. Скажи учителю, что ты закончил, или пройди главу ещё раз, чтобы получить больше звёзд.","{n} of {all} stars":"Звёзды: {n} из {all}","{ok} of {n} checks right":"Верных ответов: {ok} из {n}","Back to class":"Вернуться к классу","All done. Your teacher can see your stars now.":"Всё готово. Теперь учитель видит твои звёзды.","Play again":"Играть снова","Let's go!":"Поехали!","Build the flowchart":"Собери блок-схему","Plan first":"Сначала план","Tap the shapes in the order the chart runs them: boxes are actions, diamonds are questions. Then the shelf opens, and your blocks must follow the chart.":"Нажимай на фигуры в том порядке, в котором их выполняет схема: прямоугольники — действия, ромбы — вопросы. Потом откроется полка, и твои блоки должны следовать схеме.","Tap the plan lines in the order Bolt should do them. Then the shelf opens.":"Нажимай на строки плана в том порядке, в котором Болт должен их выполнить. Потом откроется полка.","The shelf is open.":"Полка открыта.","Hint {n} of 3":"Подсказка {n} из 3","This hint shows a move, so the third star stays in the box this time.":"Эта подсказка показывает ход, поэтому третья звезда в этот раз останется в коробке.","Got it":"Понятно","Route check":"Проверка маршрута","How sure were you?":"Насколько ты был уверен?","Not yet":"Пока нет","Getting it":"Почти","Got it!":"Понятно!","Read aloud":"Читать вслух","Sound and more":"Звук и другое","Keyboard: 1 to 8 add a block, Delete removes it, R or Ctrl+Enter runs.":"Клавиатура: 1–8 добавляют блок, Delete удаляет его, R или Ctrl+Enter запускает.","Enter a quest code":"Ввести код задания","Delete":"Стереть","Go":"Вперёд","Four digits, please.":"Нужно четыре цифры.","Close":"Закрыть","No chapter has that number yet.":"Главы с таким номером пока нет.","No band has that number.":"Группы с таким номером нет.","Task {n} of {total}":"Задача {n} из {total}","Your own level":"Твой собственный уровень","Paint a board, press Check, then hand the device to a friend to test it.":"Нарисуй поле, нажми Проверить, а потом дай устройство другу, чтобы он проверил уровень.","goal":"цель","gem":"кристалл","key":"ключ","Bolt":"Болт","Square {x}, {y}: {what}":"Клетка {x}, {y}: {what}","Tiles":"Плитки","{tile} tile":"плитка: {tile}","Check":"Проверить","Test with a friend":"Проверить с другом","Level code":"Код уровня","Skip task":"Пропустить задачу","Task skipped":"Задача пропущена","What did your tester say?":"Что сказал тот, кто проверял?","One fun thing:":"Одна весёлая вещь:","The route":"Маршрут","The gems":"Кристаллы","The tricky corner":"Хитрый угол","The door":"Дверь","One confusing thing:":"Одна непонятная вещь:","Too easy":"Слишком легко","Too hard":"Слишком сложно","A dead end":"Тупик","Nothing":"Ничего","Change one thing, then press Check again":"Измени одну вещь, потом снова нажми Проверить","Not now":"Не сейчас","Save level":"Сохранить уровень","My levels":"Мои уровни","Enter a code":"Ввести код","Clear board":"Очистить поле","Next task":"Следующая задача","The tasks":"Задачи","based on {code}":"по мотивам {code}","Improved after a test":"Улучшено после проверки","Four gems at most.":"Не больше четырёх кристаллов.","Level fixed!":"Уровень исправлен!","Task {n} done!":"Задача {n} выполнена!","Now make your own!":"Теперь сделай свой!","Plan it on paper, paint it, press Check, then hand the device to a friend to test it.":"Придумай его на бумаге, нарисуй, нажми Проверить, а потом дай устройство другу, чтобы он проверил уровень.","Press Check first: a level must be solvable before a friend tests it.":"Сначала нажми Проверить: уровень должен решаться, прежде чем его проверит друг.","Hand the device to your tester. Stay quiet and watch: say nothing until they are done.":"Передай устройство тому, кто проверяет. Молчи и смотри: ничего не говори, пока он не закончит.","Ready":"Готов","Read it out or write it on the board: a friend types it in with Enter a code on their device.":"Прочитай его вслух или напиши на доске: друг введёт его через Ввести код на своём устройстве.","Place Bolt and the goal first. Then the board gets a code.":"Сначала поставь Болта и цель. Потом у поля появится код.","Open level":"Открыть уровень","That code does not open a level. Check every symbol.":"Этот код не открывает уровень. Проверь каждый символ.","A remix: change the board, keep the based-on stamp, press Check.":"Ремикс: измени поле, оставь отметку по мотивам, нажми Проверить.","Level opened.":"Уровень открыт.","Saved. {n} levels in your box.":{"one":"Сохранено. В твоей коробке {n} уровень.","few":"Сохранено. В твоей коробке {n} уровня.","many":"Сохранено. В твоей коробке {n} уровней.","other":"Сохранено. В твоей коробке {n} уровня."},"No saved levels yet. Press Save level in the maker.":"Сохранённых уровней пока нет. Нажми Сохранить уровень в конструкторе.","Sequences":"Последовательности","Loops":"Циклы","Conditionals & events":"Условия и события","Variables":"Переменные","Functions":"Функции","Debug Lab":"Лаборатория отладки","Best Route":"Лучший маршрут","Level Maker":"Конструктор уровней","move":"вперёд","turn left":"повернуть налево","turn right":"повернуть направо","pick up":"поднять","drop":"положить","repeat":"повторить","repeat until goal":"повторять до цели","repeat until wall ahead":"повторять до стены впереди","if":"если","if / else":"если / иначе","when":"когда","set":"задать","change by":"изменить на","My Block":"Мой блок","call":"вызвать","floor":"пол","wall":"стена","water":"вода","door":"дверь","path ahead":"путь свободен","wall ahead":"впереди стена","on a gem":"на кристалле","something to pick up":"есть что поднять","on paint":"на краске","I have the key":"у меня ключ","on the button":"на кнопке","on the goal":"на цели","a gem is picked up":"кристалл поднят","Bolt bumps":"Болт врезается","the button is pressed":"кнопка нажата","Picks up the gems":"Собирает кристаллы","Drives down the side":"Едет вниз вдоль стороны","Drives to the goal":"Едет к цели","Spins around on the spot":"Крутится на месте","Climbs a zigzag staircase":"Поднимается по лестнице зигзагом","Drives straight up":"Едет прямо вверх","based on Starter blocks":"по мотивам Начальных блоков","by the Robo Route team":"от команды Robo Route","Place Bolt first.":"Сначала поставь Болта.","Place the goal flag.":"Поставь флажок цели.","A door needs a key, or gems to count.":"Двери нужен ключ или кристаллы для счёта.","No way to the goal. Open a path, or put the key before the door.":"К цели нет пути. Открой проход или положи ключ перед дверью.","Solvable, but par is only {n}. Make it harder.":"Решается, но пар всего {n}. Сделай сложнее.","Add a gem.":"Добавь кристалл.","Add a key.":"Добавь ключ.","Add a door.":"Добавь дверь.","Change at least {n} squares.":{"one":"Измени хотя бы {n} клетку.","few":"Измени хотя бы {n} клетки.","many":"Измени хотя бы {n} клеток.","other":"Измени хотя бы {n} клетки."},"Solvable! Par {n}.":"Решается! Пар {n}.","What should a player have to figure out on your board?":"Что игрок должен будет понять на твоём поле?","Place Bolt and the goal first, then press Check. Walls and water make the route; gems and a key make a quest.":"Сначала поставь Болта и цель, потом нажми Проверить. Стены и вода задают маршрут; кристаллы и ключ превращают его в задание.","A good first level: one corner, one gem, a par of six or more.":"Хороший первый уровень: один угол, один кристалл, пар шесть или больше.","Count the squares, or let a loop count them.":"Посчитай клетки или пусть их посчитает цикл.","A corner needs a turn. A gem needs a pick up where Bolt stands.":"Углу нужен поворот. Кристаллу нужно поднять там, где стоит Болт.","Drive to the first turn, turn, then drive again.":"Доедь до первого поворота, повернись и снова поезжай.","What changes from day to day on this board? Bolt has to notice it as it drives.":"Что на этом поле меняется день ото дня? Болт должен заметить это по дороге.","Build the loop first, then put the if or when inside it.":"Сначала построй цикл, потом положи в него если или когда.","The corner is somewhere along the way. Let Bolt feel for it with an if.":"Угол где-то по дороге. Пусть Болт нащупает его с помощью если.","Paint marks the corners. Move, then ask: on paint?":"Краска отмечает углы. Поезжай вперёд, потом спроси: на краске?","A bump can be useful: catch it with a when block and turn.":"Удар может быть полезным: поймай его блоком когда и повернись.","Pick up only when there is a gem under Bolt.":"Поднимай, только когда под Болтом есть кристалл.","One rule for every wall: if the path is clear move, else turn.":"Одно правило для каждой стены: если путь свободен — вперёд, иначе повернуть.","The door wants the true number of gems in the count box.":"Двери нужно настоящее число кристаллов в коробке count.","Two questions every step: a gem here? a path ahead?":"Два вопроса на каждом шаге: здесь кристалл? путь свободен?","red":"красный","blue":"синий","green":"зелёный","yellow":"жёлтый","a repeat block":"блок повторить","a repeat inside a repeat":"повтор внутри повтора","an if block":"блок если","a when block":"блок когда","a call block":"блок вызвать","a My Block":"Мой блок","a set block":"блок задать","a change block":"блок изменить","and":"и","or":"или","Explorer":"Исследователь","Pro":"Профи","An algorithm is a list of steps in order":"Алгоритм — это список шагов по порядку","Bolt does exactly what the blocks say, one after another, from the top. Tap a block on the shelf to add it to the program, then press Run.":"Болт делает ровно то, что говорят блоки, один за другим, сверху вниз. Нажми на блок на полке, чтобы добавить его в программу, а потом нажми Пуск.","How many squares does Bolt move to reach the flag?":"На сколько клеток Болт едет до флажка?","The numbers on the floor count the squares. The flag square counts too.":"Числа на полу считают клетки. Клетка с флажком тоже считается.","Use one move block for each square, up to and including the flag square.":"Используй один блок вперёд на каждую клетку, включая клетку с флажком.","Bolt runs the blocks...":"Болт выполняет блоки...","in order, from the top":"по порядку, сверху вниз","all at the same time":"все сразу","in any order it likes":"в любом порядке, как захочет","Count the squares from Bolt to the flag. The flag square counts too.":"Посчитай клетки от Болта до флажка. Клетка с флажком тоже считается.","Does a turn block move Bolt forward?":"Двигает ли блок поворота Болта вперёд?","A turn spins Bolt on the spot. After the turn, Bolt still needs move blocks.":"Поворот разворачивает Болта на месте. После поворота Болту всё равно нужны блоки вперёд.","Start with the moves that reach the turn, then one turn left block.":"Начни с ходов вперёд до поворота, потом один блок повернуть налево.","What does turn left do?":"Что делает повернуть налево?","Bolt spins to face left and stays on its square":"Болт поворачивается налево и остаётся на своей клетке","Bolt moves one square to the left":"Болт переходит на одну клетку влево","Bolt goes back to the start":"Болт возвращается на старт","Stand on the gem, then pick it up. Bolt only picks up what is under it.":"Встань на кристалл, а потом подними его. Болт поднимает только то, что под ним.","Drive onto the gem first and add a pick up there. The turn comes later.":"Сначала заедь на кристалл и добавь там поднять. Поворот будет потом.","Where does Bolt have to be when it picks up the gem?":"Где должен быть Болт, когда он поднимает кристалл?","Pick up works only on the square Bolt is standing on.":"Поднять работает только на той клетке, где стоит Болт.","The first leg is two moves, then pick up. Build that, then think about the turn.":"Первая часть — два раза вперёд, потом поднять. Собери это, а потом думай о повороте.","When does pick up work?":"Когда работает поднять?","When Bolt stands on the gem":"Когда Болт стоит на кристалле","When Bolt is next to the gem":"Когда Болт рядом с кристаллом","Any time":"Всегда","Plan first, then program":"Сначала план, потом программа","Pro programmers write the plan in plain words before they touch the blocks: this is called pseudocode. Put the plan lines in order and the shelf opens.":"Настоящие программисты пишут план простыми словами, прежде чем браться за блоки: это называется псевдокод. Расставь строки плана по порядку, и полка откроется.","Which plan line comes first?":"Какая строка плана идёт первой?","Each plan line becomes a run of blocks. Finish one line before you start the next.":"Каждая строка плана превращается в ряд блоков. Закончи одну строку, прежде чем начинать следующую.","Line 1 is four moves and a pick up. Build that leg first, then run it.":"Строка 1 — это четыре раза вперёд и поднять. Сначала собери эту часть, потом запусти.","Pseudocode is...":"Псевдокод — это...","the plan in plain words":"план простыми словами","a secret robot language":"секретный язык роботов","the fastest route":"самый быстрый маршрут","Drive to the first gem and pick it up":"Доехать до первого кристалла и поднять его","Turn and drive up to the second gem":"Повернуть и доехать вверх до второго кристалла","Turn toward the goal and drive there":"Повернуть к цели и доехать до неё","Which squares are water? Bolt cannot swim.":"Какие клетки — вода? Болт не умеет плавать.","Only one square leads into the flag without a splash: the one below it.":"Только одна клетка ведёт к флажку без плюха: та, что под ним.","Drive two squares first, then turn left to face the gap.":"Сначала проедь две клетки, потом повернись налево к проходу.","A program is a set of...":"Программа — это набор...","exact steps for the computer":"точных шагов для компьютера","ideas the computer guesses from":"идей, по которым компьютер догадывается","pictures":"картинок","How many squares is each leg of the plan?":"Сколько клеток в каждой части плана?","Count each straight run before you add its moves. Water is a splash.":"Посчитай каждый прямой участок, прежде чем добавлять ходы. Вода — это плюх.","The first leg is five moves. Then one turn right.":"Первая часть — пять раз вперёд. Потом один поворот направо.","Why write the plan first?":"Зачем сначала писать план?","It splits a long job into parts you can check":"Он делит длинную работу на части, которые можно проверить","It makes Bolt faster":"Он делает Болта быстрее","Bolt reads the plan":"Болт читает план","Drive east along the top":"Ехать на восток вдоль верхнего края","Go down and pick up the gem":"Спуститься и поднять кристалл","Drive back west":"Ехать обратно на запад","Go down to the goal":"Спуститься к цели","There are two ways to the flag. Which one has fewer steps?":"К флажку ведут два пути. На каком меньше шагов?","Going down the left side first is shorter than going along the top.":"Сначала вниз по левой стороне — короче, чем по верху.","Start with turn right: the shorter route goes down the left side first.":"Начни с повернуть направо: короткий маршрут сначала идёт вниз по левой стороне.","Two programs both reach the flag. Which is better?":"Обе программы доводят до флажка. Какая лучше?","The one with fewer steps that still works":"Та, в которой меньше шагов и которая всё равно работает","The one with more blocks":"Та, в которой больше блоков","They are always the same":"Они всегда одинаковые","Count the steps of both routes before you choose.":"Посчитай шаги обоих маршрутов, прежде чем выбрать.","The route along the top needs four turns; the route down the left needs one.":"Маршруту по верху нужно четыре поворота, а маршруту по левой стороне — один.","Start with turn right: the route down the left side is the shorter one.":"Начни с повернуть направо: маршрут по левой стороне короче.","Compare the two routes":"Сравни два маршрута","Pick the shorter one":"Выбери более короткий","Program it":"Запрограммируй его","This route has three legs. What is the first leg?":"У этого маршрута три части. Какая первая?","Leg 1: along the top to the corner. Leg 2: down. Leg 3: back along the middle to the flag.":"Часть 1: по верху до угла. Часть 2: вниз. Часть 3: обратно через середину к флажку.","Leg 1 is three moves to the gem, then pick up.":"Часть 1 — три раза вперёд до кристалла, потом поднять.","Splitting a long route into legs helps because...":"Делить длинный маршрут на части полезно, потому что...","you can check each small part":"можно проверить каждую маленькую часть","Bolt moves faster":"Болт едет быстрее","it uses fewer gems":"нужно меньше кристаллов","Name the three legs before you build.":"Назови три части, прежде чем строить.","Each leg ends with a turn. Count the squares of each leg.":"Каждая часть заканчивается поворотом. Посчитай клетки каждой части.","Leg 1 is four moves to the gem, then pick up.":"Часть 1 — четыре раза вперёд до кристалла, потом поднять.","Leg 1: east along the top, pick up the gem":"Часть 1: на восток по верху, поднять кристалл","Leg 2: turn and go down":"Часть 2: повернуть и спуститься","Leg 3: turn and go west to the goal, picking up the gem":"Часть 3: повернуть и ехать на запад к цели, подняв кристалл","A loop repeats steps":"Цикл повторяет шаги","Writing move five times is boring. A repeat block runs the blocks inside it again and again. The number says how many times.":"Писать вперёд пять раз скучно. Блок повторить снова и снова выполняет блоки внутри себя. Число говорит, сколько раз.","How many times does the move block need to run?":"Сколько раз должен выполниться блок вперёд?","Put one move block inside the repeat and set its number to the number of squares.":"Положи один блок вперёд внутрь повтора и поставь число, равное числу клеток.","Tap repeat first, then move: the move lands inside the repeat.":"Сначала нажми повторить, потом вперёд: вперёд окажется внутри повтора.","The number on a repeat block means...":"Число на блоке повторить означает...","how many times the blocks inside run":"сколько раз выполняются блоки внутри","how many squares Bolt moves in one step":"на сколько клеток Болт едет за один шаг","how many blocks you may use":"сколько блоков можно использовать","Which steps happen again and again on these stairs?":"Какие шаги повторяются на этой лестнице?","One stair is: move, turn right, move, turn left. The staircase is that stair three times.":"Одна ступенька: вперёд, повернуть направо, вперёд, повернуть налево. Лестница — это три такие ступеньки.","Put one stair inside a repeat and count the stairs for its number.":"Положи одну ступеньку в повтор и посчитай ступеньки для его числа.","What goes inside a repeat block?":"Что кладут внутрь блока повторить?","The steps that happen again and again":"Шаги, которые повторяются снова и снова","Only one move block":"Только один блок вперёд","The goal":"Цель","Bolt goes round three sides of a square. What repeats?":"Болт объезжает три стороны квадрата. Что повторяется?","Each side is three moves and a turn right.":"Каждая сторона — это три раза вперёд и один раз повернуть направо.","Put one side inside the repeat: the moves along it, then the turn.":"Положи одну сторону в повтор: ходы вдоль неё, потом поворот.","Look at the gems. Is there a pattern?":"Посмотри на кристаллы. Есть закономерность?","Every gem is two squares apart: move, move, pick.":"Кристаллы лежат через одну клетку: вперёд, вперёд, поднять.","Put a pick up block right after the second move inside the repeat.":"Положи блок поднять сразу после второго вперёд внутри повтора.","Bolt picks up a gem on every second square. A good loop body is...":"Болт поднимает кристалл на каждой второй клетке. Хорошее тело цикла — это...","move, move, pick":"вперёд, вперёд, поднять","pick, pick":"поднять, поднять","Four gems in a row: what two blocks repeat?":"Четыре кристалла в ряд: какие два блока повторяются?","Move then pick, four times. After the loop, Bolt still needs to turn and go up.":"Вперёд, потом поднять — четыре раза. После цикла Болту ещё нужно повернуть и поехать вверх.","Move then pick up inside the repeat: one pair per gem.":"Вперёд, потом поднять внутри повтора: одна пара на каждый кристалл.","Repeat 4 with move and pick inside picks up...":"Повторить 4 с вперёд и поднять внутри поднимает...","4 gems":"4 кристалла","2 gems":"2 кристалла","8 gems":"8 кристаллов","The loop will say repeat 4 with move and pick inside. How many gems will Bolt pick up?":"Цикл будет таким: повторить 4 с вперёд и поднять внутри. Сколько кристаллов поднимет Болт?","Five gems in a row: what two blocks repeat?":"Пять кристаллов в ряд: какие два блока повторяются?","Move then pick, five times. Then one more move before the turn.":"Вперёд, потом поднять — пять раз. Потом ещё один вперёд перед поворотом.","Repeat 5 with move and pick inside: how many move steps run?":"Повторить 5 с вперёд и поднять внутри: сколько шагов вперёд будет сделано?","Bolt drives round the room. Which steps come again?":"Болт объезжает комнату. Какие шаги повторяются?","Each side is three moves, a pick and a turn right. The last side has no gem.":"Каждая сторона — это три раза вперёд, поднять и повернуть направо. На последней стороне кристалла нет.","One side is three moves, pick up, turn right. Put that inside the repeat.":"Одна сторона — три раза вперёд, поднять, повернуть направо. Положи это в повтор.","After a loop ends, Bolt...":"Когда цикл заканчивается, Болт...","carries on with the blocks after the loop":"продолжает с блоками после цикла","goes back to the start":"возвращается на старт","stops for good":"останавливается насовсем","The path zigzags. What is one zig?":"Дорожка идёт зигзагом. Что такое один зиг?","One zig is: move, move, turn right, move, turn left.":"Один зиг: вперёд, вперёд, повернуть направо, вперёд, повернуть налево.","Put one zig inside the repeat and set its number to the number of zigs.":"Положи один зиг в повтор и поставь число, равное числу зигов.","The repeat count is how many times...":"Число повторов говорит, сколько раз...","the whole bracket runs":"выполняется вся скобка","Bolt turns":"Болт поворачивает","you tap Run":"ты нажимаешь Пуск","A long staircase. How many stairs?":"Длинная лестница. Сколько ступенек?","One stair: move, turn right, move, turn left. Count the stairs for the repeat number.":"Одна ступенька: вперёд, повернуть направо, вперёд, повернуть налево. Посчитай ступеньки для числа повторов.","Put one stair inside the repeat and count the stairs for its number.":"Положи одну ступеньку в повтор и посчитай ступеньки для его числа.","A loop saved you blocks because...":"Цикл сэкономил тебе блоки, потому что...","the same steps were written once and run many times":"одни и те же шаги записаны один раз и выполнены много раз","Bolt skipped squares":"Болт перепрыгнул клетки","turns are free":"повороты бесплатные","A loop inside a loop":"Цикл внутри цикла","The inner loop makes one stair. The outer loop makes the staircase. To know how many moves really ran, multiply: 3 stairs with 2 moves each is 6 moves.":"Внутренний цикл делает одну ступеньку. Внешний цикл делает лестницу. Чтобы узнать, сколько ходов выполнено на самом деле, умножь: 3 ступеньки по 2 хода — это 6 ходов.","Each stair goes up two, then across one. Can a loop make the up part?":"Каждая ступенька поднимается на две клетки и сдвигается на одну. Может ли цикл сделать подъём?","Put repeat 2 with a move inside the outer repeat. Then turn right, move, turn left.":"Положи повторить 2 с одним вперёд внутрь внешнего повтора. Потом повернуть направо, вперёд, повернуть налево.","Inside the outer repeat, start with repeat 2 holding one move: that is the up part of a stair.":"Внутри внешнего повтора начни с повторить 2 с одним вперёд: это подъём одной ступеньки.","Repeat 3 with repeat 2 with move inside: how many moves run?":"Повторить 3 с повторить 2 с вперёд внутри: сколько ходов будет сделано?","Two rows of gems. What does Bolt do for one row?":"Два ряда кристаллов. Что Болт делает для одного ряда?","One row: pick three gems, turn and come back, then step down. The outer loop does that for both rows.":"Один ряд: поднять три кристалла, развернуться и вернуться, потом спуститься на клетку. Внешний цикл делает это для обоих рядов.","Start with the inner part: repeat 3 with move and pick up clears one row.":"Начни с внутренней части: повторить 3 с вперёд и поднять очищает один ряд.","In a nested loop, the inner loop...":"Во вложенном цикле внутренний цикл...","runs completely every time the outer loop runs once":"выполняется полностью каждый раз, когда внешний делает один круг","runs only once":"выполняется только один раз","runs after the outer loop ends":"выполняется после конца внешнего цикла","Each stair has two gems going up.":"На каждой ступеньке по пути вверх два кристалла.","The inner loop climbs and picks twice; the outer loop makes three stairs.":"Внутренний цикл поднимается и подбирает дважды; внешний делает три ступеньки.","The inner loop is repeat 2 with move and pick up: that climbs one stair.":"Внутренний цикл — повторить 2 с вперёд и поднять: так Болт поднимается на одну ступеньку.","Repeat 3 with repeat 2 with move and pick inside picks up...":"Повторить 3 с повторить 2 с вперёд и поднять внутри поднимает...","6 gems":"6 кристаллов","5 gems":"5 кристаллов","3 gems":"3 кристалла","Par challenge: six blocks or fewer. Bolt goes round a square of three.":"Задача на пар: шесть блоков или меньше. Болт объезжает квадрат со стороной три.","Three sides are the same: repeat 3 with move inside, then turn right. The last side is shorter.":"Три стороны одинаковые: повторить 3 с вперёд внутри, потом повернуть направо. Последняя сторона короче.","One side is repeat 3 with move. Put that and a turn right inside an outer repeat.":"Одна сторона — повторить 3 с вперёд. Положи это и повернуть направо во внешний повтор.","Which program is shortest for three equal sides and one short side?":"Какая программа самая короткая для трёх равных сторон и одной короткой?","A loop of loops, then a small loop":"Цикл из циклов, потом маленький цикл","Twelve move blocks":"Двенадцать блоков вперёд","One big repeat 12":"Один большой повторить 12","A conditional chooses":"Условие выбирает","An if block asks a question about the world: is the path ahead clear? If yes, the blocks inside run. If no, the else blocks run. The program checks again every time.":"Блок если задаёт вопрос о мире: путь впереди свободен? Если да, выполняются блоки внутри. Если нет, выполняются блоки иначе. Программа проверяет заново каждый раз.","What should Bolt do when the path ahead is blocked?":"Что должен делать Болт, когда путь впереди закрыт?","Inside the loop: if path ahead, move; else, turn left.":"Внутри цикла: если путь свободен — вперёд; иначе — повернуть налево.","Put the if / else block inside the repeat. Move goes in the if part.":"Положи блок если / иначе внутрь повтора. Вперёд идёт в часть если.","An if block...":"Блок если...","checks a condition and chooses what to run":"проверяет условие и выбирает, что выполнить","repeats blocks":"повторяет блоки","moves Bolt":"двигает Болта","An event starts a piece of program":"Событие запускает часть программы","A when block waits for something to happen in the world. When Bolt picks up a gem, the blocks inside run right then. An if asks; a when listens.":"Блок когда ждёт, пока в мире что-то случится. Когда Болт поднимает кристалл, блоки внутри сразу выполняются. Если спрашивает; когда слушает.","Every gem sits on a corner. What should happen when Bolt picks one up?":"Каждый кристалл лежит в углу. Что должно случиться, когда Болт его поднимает?","A when gem block with turn right inside. The loop keeps moving and picking.":"Блок когда кристалл поднят с повернуть направо внутри. Цикл продолжает ехать и подбирать.","Put turn right inside the when gem block.":"Положи повернуть направо внутрь блока когда кристалл поднят.","What is the difference between if and when?":"Чем если отличается от когда?","If asks a question now; when waits for something to happen":"Если задаёт вопрос сейчас; когда ждёт, пока что-то случится","They are the same":"Они одинаковые","When is for turning only":"Когда нужен только для поворотов","The corner is in a different place each time. Can Bolt feel it?":"Угол каждый раз в другом месте. Может ли Болт его почувствовать?","Repeat until goal. Inside: if path ahead move, else turn left.":"Повторять до цели. Внутри: если путь свободен — вперёд, иначе повернуть налево.","Inside repeat until goal, put an if / else with move in the if part.":"Внутри повторять до цели положи если / иначе с вперёд в части если.","Why did a fixed list of moves fail on one of the boards?":"Почему заранее записанный список ходов не сработал на одном из полей?","The corner moved, and the list could not notice":"Угол сдвинулся, а список не мог этого заметить","Bolt was too slow":"Болт был слишком медленным","The goal disappeared":"Цель исчезла","The paint marks the corners. What should Bolt do on paint?":"Краска отмечает углы. Что Болту делать на краске?","Move, then: if on paint, turn right. Keep going until the goal.":"Вперёд, потом: если на краске — повернуть направо. Продолжать до цели.","Inside the loop: move first, then an if on paint block.":"Внутри цикла: сначала вперёд, потом блок если на краске.","On every loop turn, the if block...":"На каждом круге цикла блок если...","asks its question again":"задаёт свой вопрос снова","asks only on the first turn":"спрашивает только в первый ход","never asks":"никогда не спрашивает","Bolt is going to bump. Can a bump be useful?":"Болт сейчас врежется. Может ли удар быть полезным?","A when bump block with turn left inside. Then just keep moving until the goal.":"Блок когда Болт врезается с повернуть налево внутри. Потом просто ехать вперёд до цели.","Put turn left inside the when bump block.":"Положи повернуть налево внутрь блока когда Болт врезается.","A when bump block runs...":"Блок когда Болт врезается выполняется...","each time Bolt bumps into something":"каждый раз, когда Болт во что-то врезается","once at the start":"один раз в начале","when you press Run":"когда ты нажимаешь Пуск","The gems are on different squares each time. When should Bolt pick?":"Кристаллы каждый раз на разных клетках. Когда Болту поднимать?","Only pick when there is a gem: if on a gem, pick. Then move.":"Поднимай, только если есть кристалл: если на кристалле — поднять. Потом вперёд.","Put pick up inside an if on a gem block, then one move after it.":"Положи поднять внутрь блока если на кристалле, а после него один вперёд.","Pick up with no gem under Bolt is...":"Поднять, когда под Болтом нет кристалла, — это...","a mistake: check first with if":"ошибка: сначала проверь с помощью если","fine":"нормально","a way to find gems":"способ найти кристаллы","One program for three different mazes. What is the rule at every wall?":"Одна программа для трёх разных лабиринтов. Какое правило у каждой стены?","If the path ahead is clear, move. Else, turn right. Until the goal.":"Если путь впереди свободен — вперёд. Иначе — повернуть направо. До цели.","One program solved three mazes because...":"Одна программа прошла три лабиринта, потому что...","it checked the wall every step instead of counting":"она проверяла стену на каждом шаге, а не считала","the mazes were the same":"лабиринты были одинаковые","it was long":"она была длинной","AND, OR and NOT":"И, ИЛИ и НЕ","Two questions can be joined. Wall ahead AND on a gem is true only when both are true. Wall OR paint is true when either is. NOT flips an answer.":"Два вопроса можно соединить. Впереди стена И на кристалле — правда, только когда правда оба. Стена ИЛИ краска — правда, когда правда хотя бы одно. НЕ переворачивает ответ.","A gem on a corner means turn right. A bare corner means turn left. How does Bolt tell them apart?":"Кристалл в углу значит повернуть направо. Пустой угол значит повернуть налево. Как Болт их различит?","If wall ahead AND on a gem: pick, turn right. Else if wall ahead: turn left. Else: move.":"Если впереди стена И на кристалле: поднять, повернуть направо. Иначе если впереди стена: повернуть налево. Иначе: вперёд.","Make the first if ask two things: wall ahead and on a gem.":"Пусть первое если спрашивает две вещи: впереди стена и на кристалле.","Wall ahead AND on a gem is true when...":"Впереди стена И на кристалле — правда, когда...","both are true":"правда оба","either one is true":"правда хотя бы одно","neither is true":"не правда ни одно","Some corners have a wall, some have paint. Bolt turns right at both.":"В одних углах стена, в других краска. Болт в обоих случаях поворачивает направо.","Move first. Then: if NOT path ahead OR on paint, turn right.":"Сначала вперёд. Потом: если НЕ путь свободен ИЛИ на краске — повернуть направо.","Build the question first: not path ahead, then or, then on paint.":"Сначала собери вопрос: не путь свободен, потом или, потом на краске.","NOT path ahead OR on paint is true when...":"НЕ путь свободен ИЛИ на краске — правда, когда...","the way is blocked, or Bolt stands on paint, or both":"путь закрыт, или Болт стоит на краске, или и то и другое","only when both happen":"только когда случается и то и другое","never":"никогда","One program, three mazes. What is the rule at every wall?":"Одна программа, три лабиринта. Какое правило у каждой стены?","Put the if inside the loop so it is checked at every step.":"Положи если внутрь цикла, чтобы оно проверялось на каждом шаге.","An if inside a loop is checked...":"Если внутри цикла проверяется...","every time round the loop":"на каждом круге цикла","only once":"только один раз","at the end":"в конце","The door needs the key, and the key is somewhere on the way.":"Двери нужен ключ, а ключ лежит где-то по дороге.","If there is something to pick up, pick it. Then the usual: if path move, else turn right.":"Если есть что поднять — подними. Потом как обычно: если путь свободен — вперёд, иначе повернуть направо.","Start the loop with an if something to pick up block holding pick up.":"Начни цикл с блока если есть что поднять, внутри которого поднять.","The door opened because...":"Дверь открылась, потому что...","Bolt had picked up the key before reaching it":"Болт поднял ключ до того, как доехал до неё","Bolt bumped it":"Болт в неё врезался","doors always open":"двери всегда открываются","A variable is a labeled box":"Переменная — это коробка с наклейкой","A variable is a box with a name. Set puts a number in the box. Change by adds to it. The watch pill shows what is inside right now. This door opens only when the count box says the number written on the door.":"Переменная — это коробка с именем. Задать кладёт в коробку число. Изменить на прибавляет к нему. Индикатор показывает, что внутри прямо сейчас. Эта дверь откроется, только когда в коробке count будет число, написанное на двери.","How will Bolt know it has five gems?":"Как Болт узнает, что у него пять кристаллов?","Set count to 0 first. Each time Bolt picks a gem, change count by 1.":"Сначала задай count = 0. Каждый раз, когда Болт поднимает кристалл, измени count на 1.","Put change count by 1 right after the pick up inside the repeat.":"Положи изменить count на 1 сразу после поднять внутри повтора.","Change count by 1 means...":"Изменить count на 1 значит...","add 1 to what is in the box":"прибавить 1 к тому, что лежит в коробке","put 1 in the box":"положить в коробку 1","empty the box":"опустошить коробку","How will Bolt know it has seven gems? And what will you call the box?":"Как Болт узнает, что у него семь кристаллов? И как ты назовёшь коробку?","Pick a name a partner would understand, like count. Set it to 0, then change it by 1 for each gem.":"Выбери имя, понятное напарнику, например count. Задай 0, потом изменяй на 1 за каждый кристалл.","Name the box count, then put change count by 1 right after the pick up.":"Назови коробку count, потом положи изменить count на 1 сразу после поднять.","The door opens when the box holds the true number of gems. The number changes each time.":"Дверь открывается, когда в коробке настоящее число кристаллов. Число каждый раз другое.","Count only when there really is a gem: if on a gem, pick and change count by 1.":"Считай, только когда кристалл правда есть: если на кристалле — поднять и изменить count на 1.","Inside the if on a gem block: pick up, then change count by 1.":"Внутри блока если на кристалле: поднять, потом изменить count на 1.","What is in the count box at the end?":"Что в коробке count в конце?","The number of gems Bolt picked up":"Число кристаллов, которые поднял Болт","Always 5":"Всегда 5","The number of moves":"Число ходов","This door opens when the steps box reaches 0. Start high, count down.":"Эта дверь открывается, когда коробка steps доходит до 0. Начни с большого числа и считай назад.","Set steps to 4. Each time round, change steps by -1 before you move.":"Задай steps = 4. На каждом круге меняй steps на -1, прежде чем ехать вперёд.","Set steps to the number of squares before the door, then change it by -1 inside the loop.":"Задай steps равным числу клеток до двери, потом меняй на -1 внутри цикла.","Set empties the box and puts in a new number. Change...":"Задать опустошает коробку и кладёт новое число. Изменить...","adds to or takes from what is there":"прибавляет к тому, что там есть, или отнимает","does the same as set":"делает то же, что задать","deletes the box":"удаляет коробку","Set steps to 6. Each time round, change steps by -1 before you move.":"Задай steps = 6. На каждом круге меняй steps на -1, прежде чем ехать вперёд.","This door opens after exactly two bumps. Who counts them?":"Эта дверь открывается ровно после двух ударов. Кто их считает?","When bump: change bumps by 1 and turn right. The loop just moves.":"Когда Болт врезается: изменить bumps на 1 и повернуть направо. Цикл просто едет вперёд.","Put change bumps by 1 inside the when bump block, before the turn.":"Положи изменить bumps на 1 внутрь блока когда Болт врезается, перед поворотом.","The bumps box went up because...":"Коробка bumps выросла, потому что...","the when bump block changed it each time":"блок когда Болт врезается менял её каждый раз","Bolt moved":"Болт двигался","it counts on its own":"она считает сама","Two boxes at once":"Две коробки сразу","A program can keep many boxes. Here gems counts the gems and turns counts the corners. Each box has its own name, so you always know which is which.":"В программе может быть много коробок. Здесь gems считает кристаллы, а turns — углы. У каждой коробки своё имя, поэтому всегда понятно, какая есть какая.","Two things to count: gems and turns. Two boxes.":"Нужно считать две вещи: кристаллы и повороты. Две коробки.","When bump: change turns by 1 and turn right. In the loop: if on a gem, pick and change gems by 1.":"Когда Болт врезается: изменить turns на 1 и повернуть направо. В цикле: если на кристалле — поднять и изменить gems на 1.","Set both boxes to 0 first. Then change gems by 1 goes right after the pick up.":"Сначала задай обеим коробкам 0. Потом изменить gems на 1 ставится сразу после поднять.","Why give each box its own name?":"Зачем давать каждой коробке своё имя?","So you know which number is which":"Чтобы знать, какое число какое","Boxes need names to exist":"Без имени коробки не бывает","Names make Bolt faster":"Имена делают Болта быстрее","Gems in different places, a corner, and a door that wants the true count.":"Кристаллы в разных местах, угол и дверь, которой нужен настоящий счёт.","When bump: turn left. In the loop: if on a gem, pick and change count by 1. Then move.":"Когда Болт врезается: повернуть налево. В цикле: если на кристалле — поднять и изменить count на 1. Потом вперёд.","Put change count by 1 right after the pick up, inside the if on a gem block.":"Положи изменить count на 1 сразу после поднять, внутри блока если на кристалле.","A variable is useful when...":"Переменная полезна, когда...","a number changes while the program runs":"число меняется, пока работает программа","the number never changes":"число никогда не меняется","there are no gems":"кристаллов нет","Three kinds of boxes":"Три вида коробок","A number box holds a count. A flag box is a true/false (Boolean) box: on or off, like hasKey. A word box holds a word from a list, like color. Pick the kind that fits what you store.":"Коробка-число хранит счёт. Коробка-флажок — это коробка правда/ложь (логическая): вкл или выкл, как hasKey. Коробка-слово хранит слово из списка, как color. Выбери вид, который подходит к тому, что ты хранишь.","The door reads a flag: hasKey must be on, and Bolt must really hold the key. When does the flag become true?":"Дверь читает флажок: hasKey должен быть вкл, и ключ должен правда быть у Болта. Когда флажок становится правдой?","Set hasKey off at the start. When Bolt picks the key up, set hasKey on.":"В начале задай hasKey = выкл. Когда Болт поднимет ключ, задай hasKey = вкл.","Right after the pick up, add set hasKey to on.":"Сразу после поднять добавь задать hasKey = вкл.","A flag variable holds...":"Переменная-флажок хранит...","on or off":"вкл или выкл","any number":"любое число","a picture":"картинку","The door shows the word it wants. Which box holds words?":"Дверь показывает нужное слово. Какая коробка хранит слова?","Set color to the word on the door, then drive.":"Задай color равным слову на двери, потом поезжай.","Start with a set block: color gets the word written on the door.":"Начни с блока задать: color получает слово, написанное на двери.","A word variable holds...":"Переменная-слово хранит...","a word from a list":"слово из списка","a number":"число","This program works, but a partner cannot read it. What is x?":"Эта программа работает, но напарник не может её прочитать. Что такое x?","Tap a set or change block and give the box a name that says what it holds.":"Нажми на блок задать или изменить и дай коробке имя, которое говорит, что в ней.","Rename x to count in every block that uses it.":"Переименуй x в count во всех блоках, где она используется.","Why is x a bad name here?":"Почему x здесь плохое имя?","It does not say what the box holds":"Оно не говорит, что лежит в коробке","It is too long":"Оно слишком длинное","Letters are not allowed":"Буквы запрещены","Name a group of steps once, use it everywhere":"Дай имя группе шагов один раз и используй её везде","A My Block is a group of steps with a name. Make it once; then a call block runs the whole group wherever you put it. Here the block Stair is already made for you: call it for every stair.":"Мой блок — это группа шагов с именем. Создай её один раз; потом блок вызвать выполнит всю группу, куда бы ты его ни поставил. Здесь блок Stair уже готов: вызывай его для каждой ступеньки.","The block Stair is already made. How do you run it?":"Блок Stair уже готов. Как его выполнить?","Tap call on the shelf: one call runs everything inside Stair.":"Нажми вызвать на полке: один вызов выполняет всё, что внутри Stair.","Add one call Stair block and run it: Bolt climbs one stair.":"Добавь один блок вызвать Stair и запусти: Болт поднимется на одну ступеньку.","A My Block is...":"Мой блок — это...","a group of steps with a name you can use again":"группа шагов с именем, которую можно использовать снова","a kind of wall":"вид стены","the goal flag":"флажок цели","A procedure is a group of steps with a name. Define it once; a call runs the whole group. Three identical rooms, one block named Room: call it three times, then one more move to the goal.":"Процедура — это группа шагов с именем. Её определяют один раз; вызов выполняет всю группу. Три одинаковые комнаты, один блок по имени Room: вызови его три раза, потом ещё один вперёд до цели.","The block Room is already made. How do you run it?":"Блок Room уже готов. Как его выполнить?","Tap call on the shelf: one call runs everything inside Room.":"Нажми вызвать на полке: один вызов выполняет всё, что внутри Room.","Add one call Room block and run it: Bolt clears one room.":"Добавь один блок вызвать Room и запусти: Болт очистит одну комнату.","A procedure is...":"Процедура — это...","Bolt drives round three sides of a square. What is one side?":"Болт объезжает три стороны квадрата. Что такое одна сторона?","The block Side is one side and a turn. After three calls Bolt still needs two moves.":"Блок Side — это одна сторона и поворот. После трёх вызовов Болту ещё нужно два раза вперёд.","Add call Side once and watch what one call does.":"Добавь один раз вызвать Side и посмотри, что делает один вызов.","What does a call block do?":"Что делает блок вызвать?","Runs all the steps inside the named block":"Выполняет все шаги внутри блока с этим именем","Deletes the block":"Удаляет блок","Makes Bolt call for help":"Заставляет Болта звать на помощь","Three sides of a big square. Make one block for a side.":"Три стороны большого квадрата. Сделай один блок для стороны.","Inside Side: repeat 5 with move, then turn right. Call it three times.":"Внутри Side: повторить 5 с вперёд, потом повернуть направо. Вызови его три раза.","Make My Block Side first: one side is a repeat with move inside, then a turn right.":"Сначала сделай Мой блок Side: одна сторона — это повтор с вперёд внутри, потом повернуть направо.","This route has two legs. What would you name each leg?":"У этого маршрута две части. Как бы ты назвал каждую?","Make one block for going up and one for going across. Then call both.":"Сделай один блок для подъёма и один для перехода. Потом вызови оба.","Make My Block Up with four moves inside, then call it.":"Сделай Мой блок Up с четырьмя вперёд внутри, потом вызови его.","Why split a long route into named parts?":"Зачем делить длинный маршрут на части с именами?","Each part is easier to check and to use again":"Каждую часть легче проверить и использовать снова","Bolt drives faster":"Болт едет быстрее","You must use more blocks":"Приходится брать больше блоков","A parameter: one block, many jobs":"Параметр: один блок, много дел","These rooms have different depths. Instead of three blocks, make one block Room that takes a number: steps. Inside, repeat steps times. Each call gives its own number: Room(1), Room(3), Room(2).":"У этих комнат разная глубина. Вместо трёх блоков сделай один блок Room, который принимает число: steps. Внутри повтори steps раз. Каждый вызов даёт своё число: Room(1), Room(3), Room(2).","The rooms are 1, 3 and 2 deep. One block for all three?":"Глубина комнат 1, 3 и 2. Один блок на все три?","Give Room a number, steps. Inside, repeat steps with move, both going in and coming back.":"Дай Room число, steps. Внутри повтори steps раз вперёд — и туда, и обратно.","Give Room a number: tap the block, choose Takes a number, then use steps in its repeat.":"Дай Room число: нажми на блок, выбери Принимает число и используй steps в его повторе.","A parameter lets one block...":"Параметр позволяет одному блоку...","do the same job with a different number each time":"делать одну и ту же работу каждый раз с другим числом","run without being called":"работать без вызова","change the board":"менять поле","Remix a starter block":"Сделай ремикс начального блока","The Starter blocks shelf gives you blocks other people made. You may change them: that is a remix. Keep the line that says where the block came from, so everyone knows who started it.":"На полке Начальные блоки лежат блоки, которые сделали другие люди. Их можно менять: это называется ремикс. Оставь строку, где сказано, откуда взялся блок, чтобы все знали, кто его начал.","Zig climbs one square, then steps across. These stairs are two squares tall.":"Zig поднимается на клетку, потом шагает вбок. Эти ступеньки высотой в две клетки.","Open Zig and add one more move at the start. Keep its credit line on.":"Открой Zig и добавь ещё один вперёд в начало. Строку автора оставь.","After the remix, call Zig twice: one call per stair.":"После ремикса вызови Zig два раза: один вызов на ступеньку.","When you remix a block someone else made, you...":"Когда ты делаешь ремикс чужого блока, ты...","change it and keep the line saying where it came from":"меняешь его и оставляешь строку о том, откуда он взялся","must never change it":"никогда не можешь его менять","delete the credit line":"удаляешь строку автора","Every straight run ends with a right turn. Only the length changes.":"Каждый прямой участок заканчивается поворотом направо. Меняется только длина.","Make Dash(n): repeat n move, then turn right. Call it with each length.":"Сделай Dash(n): повторить n раз вперёд, потом повернуть направо. Вызывай его с каждой длиной.","Inside Dash, set the repeat to Use n. Then call Dash with 7 for the first run.":"Внутри Dash поставь повтор на Использовать n. Потом вызови Dash с 7 для первого участка.","Dash(7) and Dash(3) run the same block with...":"Dash(7) и Dash(3) выполняют один и тот же блок с...","a different number":"другим числом","a different robot":"другим роботом","no difference":"никакой разницы","The starter blocks almost fit. Which one is one step short?":"Начальные блоки почти подходят. Какому не хватает одного шага?","Dash is three moves; this corridor is four. Remix Dash, keep the credit line.":"В Dash три раза вперёд, а этот коридор длиной четыре. Сделай ремикс Dash и оставь строку автора.","Add one more move to Dash, then start the program with call Dash.":"Добавь в Dash ещё один вперёд, потом начни программу с вызвать Dash.","A remix is...":"Ремикс — это...","someone else's block, changed to fit a new job":"чужой блок, изменённый для новой работы","a brand new block":"совсем новый блок","a mistake":"ошибка","Three subgoals":"Три подзадачи","A big job is easier as three small ones: collect the gems, climb the stairs, cross to the goal. Make one block for each subgoal and give it a name that says what it does. Then the main program is just three calls.":"Большую работу легче сделать как три маленькие: собрать кристаллы, подняться по лестнице, дойти до цели. Сделай блок для каждой подзадачи и дай ему имя, которое говорит, что он делает. Тогда главная программа — это всего три вызова.","Name the three parts of this route before you build anything.":"Назови три части этого маршрута, прежде чем что-то строить.","One block collects the gems, one climbs, one crosses. The main program calls them in order.":"Один блок собирает кристаллы, другой поднимается, третий проходит. Главная программа вызывает их по порядку.","Make the first block GetGems: a repeat with move and pick up inside.":"Сделай первый блок GetGems: повтор с вперёд и поднять внутри.","Decomposition means...":"Декомпозиция — это...","splitting a big problem into smaller parts":"деление большой задачи на части поменьше","making the program longer":"удлинение программы","deleting blocks":"удаление блоков","Three legs: up, across, down. Which leg has the gem?":"Три части: вверх, поперёк, вниз. В какой части кристалл?","Make a block for each leg. Across picks up the gem halfway.":"Сделай блок для каждой части. Поперёк поднимает кристалл на полпути.","Three named legs make a program...":"Три части с именами делают программу...","easier to read and to fix":"проще для чтения и исправления","slower":"медленнее","impossible to run":"невозможной для запуска","Document it":"Опиши это","A note chip on a block tells a partner what the block does without reading every step. Pin the chip that matches each block: the level checks that your notes tell the truth.":"Заметка на блоке говорит напарнику, что делает блок, без чтения каждого шага. Прикрепи к каждому блоку подходящую заметку: уровень проверит, что заметки говорят правду.","Three blocks, three jobs: along the top, down the side, home. Each needs a note chip.":"Три блока, три дела: по верху, вниз вдоль стороны, домой. Каждому нужна заметка.","Open a block, tap Note chip and pick the sentence that says what it really does.":"Открой блок, нажми Заметка и выбери фразу, которая говорит, что он делает на самом деле.","Sweep drives along the top collecting gems, so its chip is Picks up the gems.":"Sweep едет по верху и собирает кристаллы, поэтому его заметка — Собирает кристаллы.","A note chip on a block should say...":"Заметка на блоке должна говорить...","what the block does, truthfully":"что делает блок, честно","how many stars you have":"сколько у тебя звёзд","the name of the robot":"как зовут робота","The shelf block Zigzag was made by someone else. How many zigs does this staircase have?":"Блок Zigzag с полки сделал кто-то другой. Сколько зигов у этой лестницы?","Call Zigzag with 5. Then make your own block for the last two squares, with its own note chip. Leave the credit line on Zigzag alone.":"Вызови Zigzag с 5. Потом сделай свой блок для последних двух клеток, со своей заметкой. Строку автора у Zigzag не трогай.","Start with call Zigzag and set its number to the number of zigs.":"Начни с вызвать Zigzag и поставь число, равное числу зигов.","When you use a block someone else made, the credit line...":"Когда ты используешь чужой блок, строка автора...","stays on, so everyone knows who made it":"остаётся, чтобы все знали, кто его сделал","should be deleted":"должна быть удалена","makes Bolt slower":"замедляет Болта","Expected and actual":"Ожидание и результат","This program has a bug. Press Step to run it one block at a time and watch where Bolt first does something you did not expect. Fix only that block: the fewest edits earn the most stars.":"В этой программе ошибка. Нажми Шаг, чтобы выполнять её по одному блоку, и посмотри, где Болт впервые делает что-то неожиданное. Исправь только этот блок: чем меньше правок, тем больше звёзд.","Step through it. At which block does Bolt first go the wrong way?":"Пройди по шагам. На каком блоке Болт впервые едет не туда?","After three moves Bolt should turn toward the flag. Which way is that?":"После трёх вперёд Болт должен повернуть к флажку. В какую это сторону?","Change the turn left into turn right.":"Замени повернуть налево на повернуть направо.","A bug is...":"Баг — это...","a mistake in a program":"ошибка в программе","an insect on the board":"жук на поле","a kind of block":"вид блока","Bolt bumps right at the end. One too many of what?":"Болт врезается в самом конце. Одного чего слишком много?","Count the squares between Bolt and the flag, then look at the repeat number.":"Посчитай клетки между Болтом и флажком, потом посмотри на число повторов.","Change the repeat from 6 to 5.":"Замени повтор 6 на 5.","Bolt bumped the wall one step after the flag. The bug is...":"Болт врезался в стену через шаг после флажка. Ошибка в том, что...","the loop runs one time too many":"цикл делает один круг лишний","the flag is in the wrong place":"флажок стоит не там","move is broken":"вперёд сломан","Bolt reached the flag but the level is not done. What is still on the board?":"Болт доехал до флажка, но уровень не пройден. Что ещё осталось на поле?","Bolt drove over the gem. Which block is missing, and where?":"Болт проехал по кристаллу. Какого блока не хватает и где?","Add a pick up after the second move.":"Добавь поднять после второго вперёд.","Bolt finished on the flag but a gem was left. The fix is...":"Болт закончил на флажке, но кристалл остался. Исправить — значит...","add the missing block in the right place":"добавить недостающий блок в нужное место","delete everything and start again":"стереть всё и начать заново","add more moves":"добавить ещё вперёд","Bolt turns when it should move and moves when it should turn. Look at the question in the if.":"Болт поворачивает, когда надо ехать, и едет, когда надо поворачивать. Посмотри на вопрос в если.","The if asks wall ahead. What should it ask so that yes means move?":"Если спрашивает впереди стена. Что оно должно спрашивать, чтобы да значило вперёд?","Change the condition from wall ahead to path ahead.":"Замени условие впереди стена на путь свободен.","The program moved when it should have turned. The bug was in...":"Программа поехала, когда надо было повернуть. Ошибка была в...","the condition of the if":"условии блока если","the number of gems":"числе кристаллов","the color of Bolt":"цвете Болта","All the right blocks are here. Is one of them in the wrong place?":"Все нужные блоки на месте. Может, один из них стоит не там?","Bolt turns too early. Move the turn right down one place.":"Болт поворачивает слишком рано. Сдвинь повернуть направо на одно место вниз.","Move the turn right so it comes after the second move.":"Перемести повернуть направо так, чтобы он шёл после второго вперёд.","Every block was right but the order was wrong. That is...":"Все блоки были верные, но порядок неправильный. Это...","still a bug: order matters":"всё равно баг: порядок важен","fine: order never matters":"нормально: порядок не важен","impossible":"невозможно","Step through one stair. Does Bolt end up facing the right way?":"Пройди одну ступеньку по шагам. Болт в конце смотрит в нужную сторону?","There is one block too many inside the loop. Which one?":"Внутри цикла один блок лишний. Какой?","Delete the second turn left inside the repeat.":"Удали второй повернуть налево внутри повтора.","An extra block inside a loop...":"Лишний блок внутри цикла...","runs every time round, so it breaks every stair":"выполняется на каждом круге, поэтому портит каждую ступеньку","does nothing":"ничего не делает","Two bugs this time. Watch the first gem: which way should Bolt turn?":"На этот раз две ошибки. Посмотри на первый кристалл: в какую сторону должен повернуть Болт?","The when block turns the wrong way. And is the loop long enough to reach the flag?":"Блок когда поворачивает не в ту сторону. И хватает ли длины цикла, чтобы доехать до флажка?","Change left to right in the when block, and the repeat from 6 to 8.":"В блоке когда замени налево на направо, а повтор 6 на 8.","After fixing one bug Bolt still fails. You should...":"После исправления одной ошибки Болт всё ещё не справляется. Тебе нужно...","test again and look for the next bug":"снова проверить и искать следующую ошибку","give up":"сдаться","add random blocks":"добавить случайные блоки","Test cases":"Тестовые случаи","One program, three test boards. A fix must pass them all: the tabs above the board show a tick or a cross for each test after a run. Find the test that fails, step through it, and change as little as you can.":"Одна программа, три тестовых поля. Исправление должно пройти их все: после запуска вкладки над полем показывают галочку или крестик для каждого теста. Найди тест, который не проходит, пройди его по шагам и поменяй как можно меньше.","Which test board fails? Run and read the tabs.":"Какое тестовое поле не проходит? Запусти и посмотри на вкладки.","At the corner Bolt turns the wrong way on every board. Which turn is it?":"На углу Болт на каждом поле поворачивает не туда. Какой это поворот?","Change turn right to turn left in the else part.":"В части иначе замени повернуть направо на повернуть налево.","Why test a program on more than one board?":"Зачем проверять программу больше чем на одном поле?","A bug may only show on some inputs":"Ошибка может проявиться только на некоторых входных данных","It makes the program longer":"Так программа становится длиннее","Bolt likes it":"Болту это нравится","Bolt reaches down on every square. What is wrong with that?":"Болт пытается поднять что-то на каждой клетке. Что тут не так?","Pick up only when there is a gem: wrap the pick in an if.":"Поднимай, только когда есть кристалл: оберни поднять в если.","Put the pick up inside an if on a gem.":"Положи поднять внутрь если на кристалле.","Picking up where there is no gem is...":"Поднять там, где нет кристалла, — это...","an error the tests catch":"ошибка, которую ловят тесты","always fine":"всегда нормально","The door reads the count box. Watch the pill: does the box ever change?":"Дверь читает коробку count. Смотри на индикатор: коробка хоть раз меняется?","Bolt picks gems but never counts them. Which block is missing inside the if?":"Болт поднимает кристаллы, но не считает их. Какого блока не хватает внутри если?","Add change count by 1 right after the pick up.":"Добавь изменить count на 1 сразу после поднять.","The watch pill never moved. That tells you...":"Индикатор ни разу не сдвинулся. Это значит, что...","the variable is never changed":"переменная ни разу не меняется","the door is broken":"дверь сломана","Bolt is slow":"Болт медленный","Bolt turns right on a gem that is not at a corner. Read the first condition aloud.":"Болт поворачивает направо на кристалле, который не в углу. Прочитай первое условие вслух.","Wall ahead OR on a gem is true too often. Which word should join the two questions?":"Впереди стена ИЛИ на кристалле — правда слишком часто. Какое слово должно соединять два вопроса?","Change or to and in the first if.":"В первом если замени или на и.","OR was true too often. AND is true only when...":"ИЛИ было правдой слишком часто. И — правда, только когда...","both parts are true":"правдивы обе части","either part is true":"правдива одна из частей","Two boxes: gems and count. Which one does the door read?":"Две коробки: gems и count. Какую читает дверь?","The program counts into the wrong box. Which block names count?":"Программа считает не в ту коробку. Какой блок называет count?","Change count by 1 should be change gems by 1.":"Изменить count на 1 должно быть изменить gems на 1.","The program counted into the wrong variable. The door...":"Программа считала не в ту переменную. Дверь...","read a box that stayed at 0":"прочитала коробку, которая осталась на 0","opened anyway":"всё равно открылась","counted for itself":"посчитала сама","Tests 1 and 2 pass. What is different about test 3?":"Тесты 1 и 2 проходят. Чем отличается тест 3?","Test 3 has no gems at all, so the count never reaches 2. When should the loop really stop?":"В тесте 3 вообще нет кристаллов, так что счёт никогда не дойдёт до 2. Когда цикл на самом деле должен остановиться?","Change repeat until count = 2 into repeat until on the goal.":"Замени повторять до count = 2 на повторять до на цели.","An edge case is...":"Граничный случай — это...","an unusual input that breaks a hidden assumption":"необычные входные данные, которые ломают скрытое допущение","the border of the board":"край поля","a very long program":"очень длинная программа","Bolt reaches the goal on every board, but only by bumping into each corner. This level says: never bump.":"Болт доходит до цели на каждом поле, но только врезаясь в каждый угол. Этот уровень говорит: никогда не врезайся.","Bolt only turns after a bump. Make it look before it moves: ask about the wall inside the loop.":"Болт поворачивает только после удара. Пусть смотрит, прежде чем ехать: спроси про стену внутри цикла.","Inside the loop, before the move, add: if wall ahead, turn right.":"Внутри цикла перед вперёд добавь: если впереди стена — повернуть направо.","Bolt reached the goal but bumped on the way. For this test that is...":"Болт дошёл до цели, но по дороге врезался. Для этого теста это...","a fail: the rule was never bump":"провал: правило было никогда не врезаться","a pass":"успех","extra points":"дополнительные очки","Two routes, one better":"Два маршрута, один лучше","Two programs can both reach the flag. Run each one and count: which is shorter, which has fewer blocks, which avoids trouble? Pick the better one, then make it better still.":"Обе программы могут довести до флажка. Запусти каждую и посчитай: какая короче, в какой меньше блоков, какая обходит неприятности? Выбери лучшую, а потом сделай её ещё лучше.","Run both routes. Count the blocks in each.":"Запусти оба маршрута. Посчитай блоки в каждом.","Route A goes up and across in seven blocks. Can a repeat make it shorter?":"Маршрут A поднимается и проходит поперёк за семь блоков. Может ли повтор его сократить?","Put the first three moves of Route A inside one repeat.":"Положи первые три хода вперёд маршрута A в один повтор.","Two programs both work. The better one is usually the one that...":"Обе программы работают. Лучшая — обычно та, что...","does the job with fewer steps or blocks":"делает работу за меньшее число шагов или блоков","has the most blocks":"содержит больше всего блоков","was written first":"была написана первой","Route A works but is long. Route B is short but bumps. Which is easier to fix?":"Маршрут A работает, но длинный. Маршрут B короткий, но врезается. Какой легче исправить?","Route B turns one square too early. Fix its first repeat number.":"Маршрут B поворачивает на клетку раньше. Исправь число в его первом повторе.","Change the first repeat of Route B from 3 to 4.":"Замени первый повтор маршрута B с 3 на 4.","A short program with one bug is often...":"Короткая программа с одной ошибкой часто...","the better start: fix the bug and keep it short":"лучшее начало: исправь ошибку и оставь её короткой","useless":"бесполезна","the same as a long one":"не лучше длинной","Route A is short. Why does it not count?":"Маршрут A короткий. Почему он не засчитывается?","Route B works but spins on the spot near the end. Which turns cancel each other?":"Маршрут B работает, но под конец крутится на месте. Какие повороты отменяют друг друга?","Delete the turn left and turn right that come right after each other.":"Удали повернуть налево и повернуть направо, которые идут друг за другом.","The shortest program drove into the water. Shortest is best only if...":"Самая короткая программа заехала в воду. Самая короткая лучше всех, только если...","it still works":"она всё равно работает","it has a loop":"в ней есть цикл","it has no turns":"в ней нет поворотов","Route B works with sixteen blocks. Route A has five but stops short.":"Маршрут B работает с шестнадцатью блоками. В маршруте A пять, но он не доезжает.","Count the stairs. Route A repeats one stair too few.":"Посчитай ступеньки. Маршрут A повторяет на одну ступеньку меньше.","Change Route A to repeat 4.":"Замени в маршруте A на повторить 4.","Compared to sixteen single blocks, a loop that does the same thing is...":"По сравнению с шестнадцатью отдельными блоками цикл, который делает то же самое, ...","slower for Bolt":"медленнее для Болта","less exact":"менее точен","Route A reaches the flag quickly. Why is the level not done?":"Маршрут A быстро доезжает до флажка. Почему уровень не пройден?","Route B picks up both gems. Which part of it repeats?":"Маршрут B поднимает оба кристалла. Какая его часть повторяется?","Put the first gem trip of Route B (two moves and a pick up) inside a repeat.":"Положи первую поездку к кристаллу в маршруте B (два раза вперёд и поднять) в повтор.","Route A was fast but left the gems. Comparing routes means checking...":"Маршрут A был быстрым, но оставил кристаллы. Сравнивать маршруты — значит проверять...","that they do the whole job, then how well":"что они делают всю работу, а потом насколько хорошо","only the speed":"только скорость","only the number of turns":"только число поворотов","A flowchart is a plan with shapes":"Блок-схема — это план из фигур","Boxes are actions. Diamonds are questions with a yes way and a no way. Build the flowchart first by putting its tiles in order. Then your blocks must follow it exactly: the level checks the program against the chart.":"Прямоугольники — это действия. Ромбы — это вопросы с путём для да и путём для нет. Сначала собери блок-схему, расставив её части по порядку. Потом твои блоки должны точно ей следовать: уровень сравнивает программу со схемой.","Follow the chart with your finger: what happens at the diamond?":"Проведи пальцем по схеме: что происходит в ромбе?","The chart says: until the goal, if path ahead then move, else turn right. Your blocks must say the same.":"Схема говорит: до цели, если путь свободен — вперёд, иначе повернуть направо. Твои блоки должны говорить то же самое.","The diamond is an if / else inside repeat until goal. Move goes in the if part.":"Ромб — это если / иначе внутри повторять до цели. Вперёд идёт в часть если.","In a flowchart, a diamond is...":"В блок-схеме ромб — это...","a question with a yes way and a no way":"вопрос с путём для да и путём для нет","an action":"действие","the end":"конец","Start":"Начало","Is Bolt on the goal? Yes: stop":"Болт на цели? Да: стоп","Is the path ahead clear?":"Путь впереди свободен?","Yes: move forward":"Да: ехать вперёд","No: turn right":"Нет: повернуть направо","Back to the top":"Обратно наверх","Two diamonds this time. Which question comes first in the chart?":"На этот раз два ромба. Какой вопрос в схеме идёт первым?","First: if on a gem, pick up. Then: if path ahead move, else turn right.":"Сначала: если на кристалле — поднять. Потом: если путь свободен — вперёд, иначе повернуть направо.","The first diamond is an if on a gem block holding pick up.":"Первый ромб — это блок если на кристалле, внутри которого поднять.","Two diamonds in a row mean...":"Два ромба подряд значат...","two questions asked one after the other every time round":"два вопроса, которые на каждом круге задаются друг за другом","one question asked twice":"один вопрос, заданный дважды","the chart is broken":"схема сломана","Is there a gem here? Yes: pick it up":"Здесь есть кристалл? Да: поднять его","The chart has a side branch that starts with When. Which block is that?":"В схеме есть боковая ветка, которая начинается с Когда. Какой это блок?","When Bolt bumps, turn left. The main loop just moves until the goal.":"Когда Болт врезается — повернуть налево. Главный цикл просто едет вперёд до цели.","The side branch is a when bump block: put turn left inside it.":"Боковая ветка — это блок когда Болт врезается: положи в него повернуть налево.","A When branch in the chart runs...":"Ветка Когда в схеме выполняется...","whenever its event happens, wherever the main loop is":"каждый раз, когда случается её событие, где бы ни был главный цикл","only at the end":"только в конце","When Bolt bumps: turn left":"Когда Болт врезается: повернуть налево","Move forward":"Ехать вперёд","Now the hallway is two squares longer":"Теперь коридор на две клетки длиннее","A program that counts squares breaks when the hallway grows. Test 2 is the same level with a longer hallway. Follow the flowchart: drive until the wall, turn, drive until the goal. Then both tests pass.":"Программа, которая считает клетки, ломается, когда коридор удлиняется. Тест 2 — тот же уровень с более длинным коридором. Следуй блок-схеме: езжай до стены, повернись, езжай до цели. Тогда пройдут оба теста.","The old program passes test 1. Run test 2. What changed?":"Старая программа проходит тест 1. Запусти тест 2. Что изменилось?","Counting four moves only fits the short hallway. The chart says drive until the wall.":"Отсчитать четыре вперёд подходит только для короткого коридора. Схема говорит: езжай до стены.","Replace repeat 4 with repeat until wall ahead.":"Замени повторить 4 на повторять до стены впереди.","A program that passes test 1 and fails test 2...":"Программа, которая проходит тест 1 и не проходит тест 2, ...","is not finished yet":"ещё не готова","is finished":"готова","needs more moves":"требует больше вперёд","Is there a wall ahead? No: move forward and ask again":"Впереди стена? Нет: ехать вперёд и спросить снова","Yes: turn left":"Да: повернуть налево","Is Bolt on the goal? No: move forward and ask again":"Болт на цели? Нет: ехать вперёд и спросить снова","Yes: stop":"Да: стоп","Three tests: the corner and the gems move. Only a chart-shaped program passes all three.":"Три теста: угол и кристаллы перемещаются. Все три пройдёт только программа, устроенная как схема.","Pick up if on a gem. Then: if path ahead move, else turn left.":"Поднять, если на кристалле. Потом: если путь свободен — вперёд, иначе повернуть налево.","The same program passed three different boards because...":"Одна и та же программа прошла три разных поля, потому что...","it asked questions instead of counting":"она задавала вопросы вместо того, чтобы считать","the boards were the same":"поля были одинаковые","No: turn left":"Нет: повернуть налево","Plan, build, test, improve":"Придумай, построй, проверь, улучши","In the Level Maker you paint the board: pick a tile, tap a square. Check proves a level can be solved and tells you its par. Test with a friend hands the device over. Nothing is typed: a level code carries the whole board.":"В Конструкторе уровней ты рисуешь поле: выбери плитку и нажми на клетку. Проверить доказывает, что уровень решается, и называет его пар. Проверить с другом передаёт устройство. Ничего не нужно печатать: код уровня хранит всё поле.","Where is the goal? Which squares around it are walls?":"Где цель? Какие клетки вокруг неё — стены?","Pick the floor tile and tap one wall next to the goal that touches the corridor.":"Выбери плитку пол и нажми на стену рядом с целью, которая касается коридора.","Tap the wall on the left of the goal, then press Check.":"Нажми на стену слева от цели, потом нажми Проверить.","Check turns red and says no way to the goal. That means...":"Проверить становится красным и пишет, что к цели нет пути. Это значит...","no program could ever solve the level":"ни одна программа никогда не решит этот уровень","the level is hard":"уровень сложный","Bolt is tired":"Болт устал","The goal is walled in. Open one wall so Bolt can reach it, then press Check.":"Цель окружена стенами. Открой одну стену, чтобы Болт мог до неё добраться, потом нажми Проверить.","Pick the floor tile and open a way from the corridor to the goal.":"Выбери плитку пол и открой путь от коридора к цели.","Open the two walls between the corridor and the goal, then press Check.":"Открой две стены между коридором и целью, потом нажми Проверить.","The goal is walled in. Open walls so Bolt can reach it, then press Check.":"Цель окружена стенами. Открой стены, чтобы Болт мог до неё добраться, потом нажми Проверить.","Par is the fewest commands a perfect program needs. How do you make Bolt work harder?":"Пар — это наименьшее число команд, которое нужно идеальной программе. Как заставить Болта потрудиться?","Move the goal to the far corner, or put walls in the straight way.":"Перенеси цель в дальний угол или поставь стены на прямом пути.","Put the goal in the bottom corner and a wall in the middle, then press Check.":"Поставь цель в нижний угол, а стену в середину, потом нажми Проверить.","Your tester said the level was too easy. A good next step is...":"Тот, кто проверял, сказал, что уровень слишком лёгкий. Хороший следующий шаг —...","change the level using what they said, then test again":"изменить уровень по его словам и снова проверить","tell them they played it wrong":"сказать ему, что он неправильно играл","start a new level and never test it":"начать новый уровень и никогда его не проверять","Too easy: par is 1. Move the goal or add walls until par is at least 6. Keep it solvable.":"Слишком легко: пар равен 1. Перенеси цель или добавь стены, пока пар не станет не меньше 6. Уровень должен решаться.","Move the goal far away and put a wall across the straight way.":"Поставь цель подальше, а стену поперёк прямого пути.","Put the goal in the bottom corner and a long wall in the middle, then press Check.":"Поставь цель в нижний угол, а длинную стену в середину, потом нажми Проверить.","Too easy: par is 1. Move the goal or add walls until par is at least 10. Keep it solvable.":"Слишком легко: пар равен 1. Перенеси цель или добавь стены, пока пар не станет не меньше 10. Уровень должен решаться.","A door only opens for a key. Where must the key be?":"Дверь открывается только ключом. Где должен быть ключ?","Put the key before the door on the way, and a gem anywhere Bolt can reach.":"Положи ключ на пути перед дверью, а кристалл туда, куда Болт может доехать.","Gem next to Bolt, key on the left side, door right before the goal. Then Check.":"Кристалл рядом с Болтом, ключ слева, дверь прямо перед целью. Потом Проверить.","A level with a door, no key and no gems is...":"Уровень с дверью, без ключа и без кристаллов, — это...","unsolvable: Check will refuse it":"не решается: Проверить его отклонит","harder":"сложнее","Make it a quest: add a gem, a key and a door on the way to the goal. Keep it solvable.":"Сделай из него задание: добавь кристалл, ключ и дверь на пути к цели. Уровень должен решаться.","A remix keeps the based-on stamp and changes something real.":"Ремикс сохраняет отметку по мотивам и меняет что-то по-настоящему.","Add gems, a puddle or a wall: three squares or more. Then Check.":"Добавь кристаллы, лужу или стену: три клетки или больше. Потом Проверить.","Put two gems on the way and a puddle in the bottom row, then press Check.":"Положи два кристалла на пути и лужу в нижний ряд, потом нажми Проверить.","The based-on stamp on a remixed level...":"Отметка по мотивам на уровне-ремиксе...","credits the level it came from":"называет уровень, из которого он сделан","makes it harder":"делает его сложнее","is the par":"— это пар","Remix: this level came from a code. Change at least three squares, keep it solvable, and keep the based-on stamp.":"Ремикс: этот уровень пришёл из кода. Измени хотя бы три клетки, сохрани решаемость и оставь отметку по мотивам.","Bump! A wall after step {n}. Bolt did exactly what the blocks said.":"Бум! Стена после шага {n}. Болт сделал ровно то, что говорили блоки.","The door is shut. What does it need before Bolt can go through?":"Дверь закрыта. Что ей нужно, чтобы Болт прошёл?","The door checks the box as Bolt steps in. Bolt reached the door before the box was filled, so it stayed shut. Fill the box first, then walk in.":"Дверь проверяет ящик, когда Болт входит. Болт дошёл до двери раньше, чем ящик наполнился, поэтому она осталась закрытой. Сначала наполни ящик, а потом входи.","Splash! Bolt drove into the water after step {n}.":"Плюх! Болт заехал в воду после шага {n}.","Bolt reached down after step {n}, but there was nothing to pick up there.":"После шага {n} Болт попробовал что-то поднять, но там ничего не было.","One gem is still out there.":"Один кристалл всё ещё не собран.","{n} gems are still out there.":{"one":"Ещё не собран {n} кристалл.","few":"Ещё не собраны {n} кристалла.","many":"Ещё не собрано {n} кристаллов.","other":"Ещё не собрано {n} кристалла."},"Bolt stopped, but not on the goal.":"Болт остановился, но не на цели.","Bolt ran out of energy: the program goes on and on. Is a loop going round and round?":"У Болта кончилась энергия: программа всё идёт и идёт. Может, какой-то цикл крутится по кругу?","Bolt ran out of energy: the loop never stopped. A sensor checks the square Bolt is standing on, so the answer only changes when Bolt moves to a new square.":"У Болта закончилась энергия: цикл так и не остановился. Датчик проверяет клетку, на которой стоит Болт, поэтому ответ меняется только когда Болт переходит на новую клетку.","The blocks call each other too deeply.":"Блоки вызывают друг друга слишком глубоко.","{name} is not a clear name. A partner could not tell what is in that box.":"{name} — непонятное имя. Напарник не поймёт, что лежит в этой коробке.","This level needs {block}. The learn card shows how.":"На этом уровне нужен {block}. Карточка Узнать покажет как.","Split the route into named blocks first.":"Сначала раздели маршрут на блоки с именами.","A note chip does not match what its block does.":"Заметка не совпадает с тем, что делает её блок.","Add a note chip to {name}: what does that block do?":"Добавь заметку к {name}: что делает этот блок?","Keep the block {name} and its credit line: it says where the block came from.":"Оставь блок {name} и его строку автора: она говорит, откуда взялся блок.","Remix means change something. {name} is still exactly the starter block.":"Ремикс значит что-то изменить. {name} всё ещё в точности начальный блок.","The program does not follow the flowchart. Check each box and diamond against your blocks.":"Программа не следует блок-схеме. Сравни каждый прямоугольник и каждый ромб со своими блоками.","A block is called that was never made.":"Вызывается блок, который так и не был создан.","Something in the program is not a block Bolt knows.":"В программе есть что-то, чего Болт не знает как блок.","Use the shared block {name}: call it from your program.":"Используй общий блок {name}: вызови его из своей программы.","A when block only works on its own, at the top level. Inside another block it cannot listen for anything. Move it out.":"Блок «когда» работает только сам по себе, на верхнем уровне. Внутри другого блока он ничего не может услышать. Вынеси его наружу.","A My Block only works on its own, at the top level. Inside another block it cannot be made. Move it out.":"Блок «Мой блок» работает только сам по себе, на верхнем уровне. Внутри другого блока его нельзя создать. Вынеси его наружу."}} });
